import os

# Base directory
BASE_DIR = os.path.dirname(os.path.abspath(__file__))

# ==============================================================================
# Quantum Key Distribution (QKD) Settings - Module A
# ==============================================================================
# Number of initial qubits generated by Alice
NUM_QUBITS = 512

# Basis definitions: 0 = Rectilinear (+, {|0>, |1>}), 1 = Diagonal (x, {|+>, |->})
BASIS_RECTILINEAR = 0
BASIS_DIAGONAL = 1

# Fraction of sifted bits sacrificed for public QBER estimation (e.g., 0.25 = 25%)
SAMPLE_FRACTION = 0.25

# Theoretical QBER security abort threshold (11% standard limit for BB84)
QBER_THRESHOLD = 0.11

# Eavesdropper (Eve) configuration
ENABLE_EVE = False           # Set to True to simulate active intercept-resend attack
EVE_INTERCEPT_PROB = 1.0     # Fraction of qubits intercepted by Eve when active

# Aer simulator shots (single-photon simulation)
SIMULATOR_SHOTS = 1

# ==============================================================================
# IoT & Cryptography Settings - Module B
# ==============================================================================
# AES-256-GCM specifications (NIST SP 800-38D)
AES_KEY_SIZE_BYTES = 32      # 256 bits
AES_GCM_NONCE_SIZE_BYTES = 12 # 96 bits standard unique IV/nonce
AES_GCM_TAG_SIZE_BYTES = 16   # 128 bits authentication tag

# Simulated IoT sensor configuration
DEVICE_ID = "IOT-WEATHER-STATION-01"
DEFAULT_SENSOR_INTERVAL_SEC = 2.0

# ==============================================================================
# MQTT Transport Settings
# ==============================================================================
# If True, runs an internal memory/queue broker bridge (guarantees offline zero-dependency execution)
# If False, connects to a real external/local MQTT broker via TCP
USE_SIMULATED_BROKER = True

# External MQTT broker details (used when USE_SIMULATED_BROKER = False)
MQTT_BROKER_HOST = "localhost"  # e.g., "localhost" or "broker.emqx.io"
MQTT_BROKER_PORT = 1883
MQTT_KEEPALIVE = 60

# MQTT Topics
MQTT_TOPIC_DATA = "iot/secure/data"
MQTT_TOPIC_STATUS = "iot/secure/status"

# ==============================================================================
# Cloud Storage & Dashboard Settings - Module C & E
# ==============================================================================
DATABASE_DIR = os.path.join(BASE_DIR, "database")
DATABASE_PATH = os.path.join(DATABASE_DIR, "iot_cloud.db")

DASHBOARD_HOST = "127.0.0.1"
DASHBOARD_PORT = 5000
DASHBOARD_DEBUG = False

# ==============================================================================
# Benchmarking Settings - Module F
# ==============================================================================
BENCHMARK_DIR = os.path.join(BASE_DIR, "benchmarks")
